FILE_REPLACEMENTS: dict[str, list[tuple[str, str]]] = {'ApplicationAvailability.java': [('/**\n * Provides {@link AvailabilityState availability state} information for the application.\n * <p>\n * Components can inject this class to get the current state information. To update the\n * state of the application an {@link AvailabilityChangeEvent} should be\n * {@link ApplicationContext#publishEvent published} to the application context with\n * directly or through {@link AvailabilityChangeEvent#publish}.\n *\n * @author Brian Clozel\n * @author Phillip Webb\n * @since 2.3.0\n */', '/**\n * 提供应用的 {@link AvailabilityState 可用性状态} 信息。\n * <p>\n * 组件可注入此类以获取当前状态信息。要更新应用状态，应直接向应用上下文\n * {@link ApplicationContext#publishEvent 发布} {@link AvailabilityChangeEvent}，\n * 或通过 {@link AvailabilityChangeEvent#publish} 发布。\n *\n * @author Brian Clozel\n * @author Phillip Webb\n * @since 2.3.0\n */'), ('/**\n\t * Return the {@link LivenessState} of the application.\n\t * @return the liveness state\n\t */', '/**\n\t * 返回应用的 {@link LivenessState}。\n\t *\n\t * @return 存活状态\n\t */'), ('/**\n\t * Return the {@link ReadinessState} of the application.\n\t * @return the readiness state\n\t */', '/**\n\t * 返回应用的 {@link ReadinessState}。\n\t *\n\t * @return 就绪状态\n\t */'), ('/**\n\t * Return {@link AvailabilityState} information for the application.\n\t * @param <S> the state type\n\t * @param stateType the state type\n\t * @param defaultState the default state to return if no event of the given type has\n\t * been published yet (must not be {@code null}).\n\t * @return the readiness state\n\t * @see #getState(Class)\n\t */', '/**\n\t * 返回应用的 {@link AvailabilityState} 信息。\n\t *\n\t * @param <S> 状态类型\n\t * @param stateType 状态类型\n\t * @param defaultState 尚未发布给定类型事件时返回的默认状态（不可为 {@code null}）\n\t * @return 可用性状态\n\t * @see #getState(Class)\n\t */'), ('/**\n\t * Return {@link AvailabilityState} information for the application.\n\t * @param <S> the state type\n\t * @param stateType the state type\n\t * @return the readiness state or {@code null} if no event of the given type has been\n\t * published yet\n\t * @see #getState(Class, AvailabilityState)\n\t */', '/**\n\t * 返回应用的 {@link AvailabilityState} 信息。\n\t *\n\t * @param <S> 状态类型\n\t * @param stateType 状态类型\n\t * @return 可用性状态；若尚未发布给定类型事件则为 {@code null}\n\t * @see #getState(Class, AvailabilityState)\n\t */'), ('/**\n\t * Return the last {@link AvailabilityChangeEvent} received for a given state type.\n\t * @param <S> the state type\n\t * @param stateType the state type\n\t * @return the readiness state or {@code null} if no event of the given type has been\n\t * published yet\n\t */', '/**\n\t * 返回给定状态类型收到的最后一个 {@link AvailabilityChangeEvent}。\n\t *\n\t * @param <S> 状态类型\n\t * @param stateType 状态类型\n\t * @return 最后一次变更事件；若尚未发布给定类型事件则为 {@code null}\n\t */')], 'ApplicationAvailabilityBean.java': [('/**\n * Bean that provides an {@link ApplicationAvailability} implementation by listening for\n * {@link AvailabilityChangeEvent change events}.\n *\n * @author Brian Clozel\n * @author Phillip Webb\n * @since 2.3.0\n * @see ApplicationAvailability\n */', '/**\n * 通过监听 {@link AvailabilityChangeEvent 变更事件} 提供\n * {@link ApplicationAvailability} 实现的 Bean。\n *\n * @author Brian Clozel\n * @author Phillip Webb\n * @since 2.3.0\n * @see ApplicationAvailability\n */')], 'AvailabilityChangeEvent.java': [('/**\n * {@link ApplicationEvent} sent when the {@link AvailabilityState} of the application\n * changes.\n * <p>\n * Any application component can send such events to update the state of the application.\n *\n * @param <S> the availability state type\n * @author Brian Clozel\n * @author Phillip Webb\n * @since 2.3.0\n */', '/**\n * 应用 {@link AvailabilityState} 发生变化时发送的 {@link ApplicationEvent}。\n * <p>\n * 任何应用组件均可发送此类事件以更新应用状态。\n *\n * @param <S> 可用性状态类型\n * @author Brian Clozel\n * @author Phillip Webb\n * @since 2.3.0\n */'), ('/**\n\t * Create a new {@link AvailabilityChangeEvent} instance.\n\t * @param source the source of the event\n\t * @param state the availability state (never {@code null})\n\t */', '/**\n\t * 创建新的 {@link AvailabilityChangeEvent} 实例。\n\t *\n\t * @param source 事件源\n\t * @param state 可用性状态（不可为 {@code null}）\n\t */'), ('/**\n\t * Return the changed availability state.\n\t * @return the availability state\n\t */', '/**\n\t * 返回变更后的可用性状态。\n\t *\n\t * @return 可用性状态\n\t */'), ('/**\n\t * Convenience method that can be used to publish an {@link AvailabilityChangeEvent}\n\t * to the given application context.\n\t * @param <S> the availability state type\n\t * @param context the context used to publish the event\n\t * @param state the changed availability state\n\t */', '/**\n\t * 向给定应用上下文发布 {@link AvailabilityChangeEvent} 的便捷方法。\n\t *\n\t * @param <S> 可用性状态类型\n\t * @param context 用于发布事件的上下文\n\t * @param state 变更后的可用性状态\n\t */'), ('/**\n\t * Convenience method that can be used to publish an {@link AvailabilityChangeEvent}\n\t * to the given application context.\n\t * @param <S> the availability state type\n\t * @param publisher the publisher used to publish the event\n\t * @param source the source of the event\n\t * @param state the changed availability state\n\t */', '/**\n\t * 向给定应用上下文发布 {@link AvailabilityChangeEvent} 的便捷方法。\n\t *\n\t * @param <S> 可用性状态类型\n\t * @param publisher 用于发布事件的发布器\n\t * @param source 事件源\n\t * @param state 变更后的可用性状态\n\t */')], 'AvailabilityState.java': [('/**\n * Tagging interface used on {@link ApplicationAvailability} states. This interface is\n * usually implemented on an {@code enum} type.\n *\n * @author Phillip Webb\n * @since 2.3.0\n * @see LivenessState\n * @see ReadinessState\n */', '/**\n * 用于标记 {@link ApplicationAvailability} 状态的标签接口。\n * 通常由 {@code enum} 类型实现。\n *\n * @author Phillip Webb\n * @since 2.3.0\n * @see LivenessState\n * @see ReadinessState\n */')], 'LivenessState.java': [('/**\n * "Liveness" state of the application.\n * <p>\n * An application is considered live when it\'s running with a correct internal state.\n * "Liveness" failure means that the internal state of the application is broken and we\n * cannot recover from it. As a result, the platform should restart the application.\n *\n * @author Brian Clozel\n * @since 2.3.0\n */', '/**\n * 应用的「存活（Liveness）」状态。\n * <p>\n * 当应用正在运行且内部状态正确时视为存活。「存活」失败表示应用内部状态已损坏且\n * 无法恢复，平台应重启应用。\n *\n * @author Brian Clozel\n * @since 2.3.0\n */'), ('/**\n\t * The application is running and its internal state is correct.\n\t */', '/**\n\t * 应用正在运行且内部状态正确。\n\t */'), ('/**\n\t * The application is running but its internal state is broken.\n\t */', '/**\n\t * 应用正在运行但内部状态已损坏。\n\t */')], 'ReadinessState.java': [('/**\n * "Readiness" state of the application.\n * <p>\n * An application is considered ready when it\'s {@link LivenessState live} and willing to\n * accept traffic. "Readiness" failure means that the application is not able to accept\n * traffic and that the infrastructure should stop routing requests to it.\n *\n * @author Brian Clozel\n * @since 2.3.0\n */', '/**\n * 应用的「就绪（Readiness）」状态。\n * <p>\n * 当应用 {@link LivenessState 存活} 且愿意接收流量时视为就绪。「就绪」失败表示\n * 应用无法接收流量，基础设施应停止向其路由请求。\n *\n * @author Brian Clozel\n * @since 2.3.0\n */'), ('/**\n\t * The application is ready to receive traffic.\n\t */', '/**\n\t * 应用已准备好接收流量。\n\t */'), ('/**\n\t * The application is not willing to receive traffic.\n\t */', '/**\n\t * 应用不愿意接收流量。\n\t */')], 'CloudPlatform.java': [('/**\n * Simple detection for well known cloud platforms. Detection can be forced using the\n * {@code "spring.main.cloud-platform"} configuration property.\n *\n * @author Phillip Webb\n * @author Brian Clozel\n * @author Nguyen Sach\n * @since 1.3.0\n */', '/**\n * 常见云平台检测。可通过 {@code "spring.main.cloud-platform"} 配置属性强制指定。\n *\n * @author Phillip Webb\n * @author Brian Clozel\n * @author Nguyen Sach\n * @since 1.3.0\n */'), ('/**\n\t * No Cloud platform. Useful when false-positives are detected.\n\t */', '/**\n\t * 非云平台。在出现误检测时有用。\n\t */'), ('/**\n\t * Cloud Foundry platform.\n\t */', '/**\n\t * Cloud Foundry 平台。\n\t */'), ('/**\n\t * Heroku platform.\n\t */', '/**\n\t * Heroku 平台。\n\t */'), ('/**\n\t * SAP Cloud platform.\n\t */', '/**\n\t * SAP Cloud 平台。\n\t */'), ('/**\n\t * Nomad platform.\n\t * @since 3.1.0\n\t */', '/**\n\t * Nomad 平台。\n\t * @since 3.1.0\n\t */'), ('/**\n\t * Kubernetes platform.\n\t */', '/**\n\t * Kubernetes 平台。\n\t */'), ('/**\n\t * Azure App Service platform.\n\t */', '/**\n\t * Azure App Service 平台。\n\t */'), ('/**\n\t * Amazon Web Services (AWS) Elastic Container Service (ECS) platform.\n\t * @since 4.0.0\n\t */', '/**\n\t * Amazon Web Services (AWS) Elastic Container Service (ECS) 平台。\n\t * @since 4.0.0\n\t */'), ('/**\n\t * Determines if the platform is active (i.e. the application is running in it).\n\t * @param environment the environment\n\t * @return if the platform is active.\n\t */', '/**\n\t * 判定平台是否处于活动状态（即应用是否运行在该平台上）。\n\t *\n\t * @param environment 环境\n\t * @return 平台是否活动\n\t */'), ('/**\n\t * Determines if the platform is enforced by looking at the\n\t * {@code "spring.main.cloud-platform"} configuration property.\n\t * @param environment the environment\n\t * @return if the platform is enforced\n\t * @since 2.3.0\n\t */', '/**\n\t * 通过 {@code "spring.main.cloud-platform"} 配置属性判定平台是否被强制指定。\n\t *\n\t * @param environment 环境\n\t * @return 平台是否被强制指定\n\t * @since 2.3.0\n\t */'), ('/**\n\t * Determines if the platform is enforced by looking at the\n\t * {@code "spring.main.cloud-platform"} configuration property.\n\t * @param binder the binder\n\t * @return if the platform is enforced\n\t * @since 2.4.0\n\t */', '/**\n\t * 通过 {@code "spring.main.cloud-platform"} 配置属性判定平台是否被强制指定。\n\t *\n\t * @param binder 绑定器\n\t * @return 平台是否被强制指定\n\t * @since 2.4.0\n\t */'), ('/**\n\t * Determines if the platform is detected by looking for platform-specific environment\n\t * variables.\n\t * @param environment the environment\n\t * @return if the platform is auto-detected.\n\t * @since 2.3.0\n\t */', '/**\n\t * 通过查找平台特定环境变量判定平台是否被自动检测。\n\t *\n\t * @param environment 环境\n\t * @return 平台是否被自动检测\n\t * @since 2.3.0\n\t */'), ('/**\n\t * Returns if the platform is behind a load balancer and uses\n\t * {@literal X-Forwarded-For} headers.\n\t * @return if {@literal X-Forwarded-For} headers are used\n\t */', '/**\n\t * 返回平台是否位于负载均衡器后并使用 {@literal X-Forwarded-For} 头。\n\t *\n\t * @return 是否使用 {@literal X-Forwarded-For} 头\n\t */'), ('/**\n\t * Returns the active {@link CloudPlatform} or {@code null} if one is not active.\n\t * @param environment the environment\n\t * @return the {@link CloudPlatform} or {@code null}\n\t */', '/**\n\t * 返回活动的 {@link CloudPlatform}；若无活动平台则返回 {@code null}。\n\t *\n\t * @param environment 环境\n\t * @return {@link CloudPlatform} 或 {@code null}\n\t */')], 'ApplicationPidFileWriter.java': [('/**\n * An {@link ApplicationListener} that saves application PID into file. This application\n * listener will be triggered exactly once per JVM, and the file name can be overridden at\n * runtime with a System property or environment variable named "PIDFILE" (or "pidfile")\n * or using a {@code spring.pid.file} property in the Spring {@link Environment}.\n * <p>\n * If PID file can not be created no exception is reported. This behavior can be changed\n * by assigning {@code true} to System property or environment variable named\n * {@code PID_FAIL_ON_WRITE_ERROR} (or "pid_fail_on_write_error") or to\n * {@code spring.pid.fail-on-write-error} property in the Spring {@link Environment}.\n * <p>\n * Note: access to the Spring {@link Environment} is only possible when the\n * {@link #setTriggerEventType(Class) triggerEventType} is set to\n * {@link ApplicationEnvironmentPreparedEvent}, {@link ApplicationReadyEvent}, or\n * {@link ApplicationPreparedEvent}.\n *\n * @author Jakub Kubrynski\n * @author Dave Syer\n * @author Phillip Webb\n * @author Tomasz Przybyla\n * @author Madhura Bhave\n * @since 2.0.0\n */', '/**\n * 将应用 PID 写入文件的 {@link ApplicationListener}。\n * 每个 JVM 仅触发一次；文件名可在运行时通过名为 {@code PIDFILE}（或 {@code pidfile}）\n * 的系统属性或环境变量，或 Spring {@link Environment} 中的 {@code spring.pid.file} 属性覆盖。\n * <p>\n * 若无法创建 PID 文件则不报告异常。可通过将系统属性或环境变量\n * {@code PID_FAIL_ON_WRITE_ERROR}（或 {@code pid_fail_on_write_error}）或\n * Spring {@link Environment} 中的 {@code spring.pid.fail-on-write-error} 设为 {@code true} 更改此行为。\n * <p>\n * 注意：仅当 {@link #setTriggerEventType(Class) triggerEventType} 设为\n * {@link ApplicationEnvironmentPreparedEvent}、{@link ApplicationReadyEvent} 或\n * {@link ApplicationPreparedEvent} 时才能访问 Spring {@link Environment}。\n *\n * @author Jakub Kubrynski\n * @author Dave Syer\n * @author Phillip Webb\n * @author Tomasz Przybyla\n * @author Madhura Bhave\n * @since 2.0.0\n */'), ("/**\n\t * Create a new {@link ApplicationPidFileWriter} instance using the filename\n\t * 'application.pid'.\n\t */", '/**\n\t * 使用文件名 {@code application.pid} 创建新的 {@link ApplicationPidFileWriter} 实例。\n\t */'), ('/**\n\t * Create a new {@link ApplicationPidFileWriter} instance with a specified filename.\n\t * @param filename the name of file containing pid\n\t */', '/**\n\t * 使用指定文件名创建新的 {@link ApplicationPidFileWriter} 实例。\n\t *\n\t * @param filename 包含 PID 的文件名\n\t */'), ('/**\n\t * Create a new {@link ApplicationPidFileWriter} instance with a specified file.\n\t * @param file the file containing pid\n\t */', '/**\n\t * 使用指定文件创建新的 {@link ApplicationPidFileWriter} 实例。\n\t *\n\t * @param file 包含 PID 的文件\n\t */'), ('/**\n\t * Sets the type of application event that will trigger writing of the PID file.\n\t * Defaults to {@link ApplicationPreparedEvent}. NOTE: If you use the\n\t * {@link org.springframework.boot.context.event.ApplicationStartingEvent} to trigger\n\t * the write, you will not be able to specify the PID filename in the Spring\n\t * {@link Environment}.\n\t * @param triggerEventType the trigger event type\n\t */', '/**\n\t * 设置触发写入 PID 文件的应用事件类型，默认为 {@link ApplicationPreparedEvent}。\n\t * 注意：若使用 {@link org.springframework.boot.context.event.ApplicationStartingEvent}\n\t * 触发写入，则无法在 Spring {@link Environment} 中指定 PID 文件名。\n\t *\n\t * @param triggerEventType 触发事件类型\n\t */'), ('/**\n\t * Reset the created flag for testing purposes.\n\t */', '/**\n\t * 重置 created 标志，供测试使用。\n\t */'), ('/**\n\t * Provides access to a property value.\n\t */', '/**\n\t * 提供对属性值的访问。\n\t */'), ("/**\n\t * {@link Property} obtained from Spring's {@link Environment}.\n\t */", '/**\n\t * 从 Spring {@link Environment} 获取的 {@link Property}。\n\t */'), ('/**\n\t * {@link Property} obtained from {@link SystemProperties}.\n\t */', '/**\n\t * 从 {@link SystemProperties} 获取的 {@link Property}。\n\t */')], 'BootstrapContext.java': [('Provides lazy access to singletons that may be expensive to create, or need to be\n * shared before the {@link ApplicationContext} is available.', '提供对创建成本较高或需在 {@link ApplicationContext} 可用前共享的单例的延迟访问。'), ('Instances are registered by type. The contact may return {@code null} values when a\n * type has been registered but no value is actually supplied.', '实例按类型注册。若某类型已注册但未实际提供值，上下文可能返回 {@code null}。'), ('A simple bootstrap context that is available during startup and {@link Environment}\n * post-processing up to the point that the {@link ApplicationContext} is prepared.', '在启动及 {@link Environment} 后处理期间、直至 {@link ApplicationContext} 准备完成前可用的简单引导上下文。')], 'BootstrapContextClosedEvent.java': [("/**\n * {@link ApplicationEvent} published by a {@link BootstrapContext} when it's closed.", '/**\n * {@link BootstrapContext} 关闭时发布的 {@link ApplicationEvent}。'), ('@return the bootstrap context', '@return 引导上下文'), ('@return the application context', '@return 应用上下文'), ('Return the {@link BootstrapContext} that was closed.', '返回已关闭的 {@link BootstrapContext}。'), ('Return the prepared application context.', '返回已准备的应用上下文。')], 'BootstrapRegistryInitializer.java': [('Callback interface that can be used to initialize a {@link BootstrapRegistry} before it\n * is used.', '在 {@link BootstrapRegistry} 使用前对其进行初始化的回调接口。'), ('Initialize the given {@link BootstrapRegistry} with any required registrations.', '使用所需注册项初始化给定的 {@link BootstrapRegistry}。'), ('@param registry the registry to initialize', '@param registry 要初始化的注册表')], 'ConfigurableBootstrapContext.java': [('A {@link BootstrapContext} that also provides configuration methods through the\n * {@link BootstrapRegistry} interface.', '同时通过 {@link BootstrapRegistry} 接口提供配置方法的 {@link BootstrapContext}。')], 'DefaultBootstrapContext.java': [('Default {@link ConfigurableBootstrapContext} implementation.', '{@link ConfigurableBootstrapContext} 的默认实现。'), ('Method to be called when {@link BootstrapContext} is closed and the\n * {@link ApplicationContext} is prepared.', '在 {@link BootstrapContext} 关闭且 {@link ApplicationContext} 已准备完成时调用的方法。'), ('@param applicationContext the prepared context', '@param applicationContext 已准备的上下文')], 'ParentContextApplicationContextInitializer.java': [('{@link ApplicationContextInitializer} for setting the parent context. Also publishes\n * {@link ParentContextAvailableEvent} when the context is refreshed to signal to other\n * listeners that the context is available and has a parent.', '{@link ApplicationContextInitializer} 用于设置父上下文。上下文刷新时还会发布 {@link ParentContextAvailableEvent}，通知其他监听器上下文已可用且拥有父上下文。'), ('{@link ApplicationEvent} fired when a parent context is available.', '{@link ApplicationEvent} 父上下文可用时触发。')], 'ParentContextCloserApplicationListener.java': [('Listener that closes the application context if its parent is closed. It listens for\n * refresh events and grabs the current context from there, and then listens for closed\n * events and propagates it down the hierarchy.', '在父上下文关闭时关闭应用上下文的监听器。监听刷新事件以获取当前上下文，再监听关闭事件并沿层次结构向下传播。'), ('Subclasses may override to create their own subclass of ContextCloserListener.', '子类可覆盖以创建自定义 {@link ContextCloserListener} 子类。'), ('{@link ApplicationListener} to close the context.', '{@link ApplicationListener} 用于关闭上下文。'), ('@param child the child context', '@param child 子上下文')], 'ContextIdApplicationContextInitializer.java': [('{@link ApplicationContextInitializer} that sets the Spring\n * {@link ApplicationContext#getId() ApplicationContext ID}.', '{@link ApplicationContextInitializer} 设置 Spring {@link ApplicationContext#getId() ApplicationContext ID}。'), ('The {@code spring.application.name} property is used to create the ID. If the property is\n * not set {@code application} is used.', '使用 {@code spring.application.name} 属性创建 ID；未设置时使用 {@code application}。'), ('The ID of a context.', '上下文 ID。')], 'ConfigurationWarningsApplicationContextInitializer.java': [('{@link ApplicationContextInitializer} to report warnings for common misconfiguration\n * mistakes.', '{@link ApplicationContextInitializer} 报告常见配置错误。'), ('Returns the checks that should be applied.', '返回应执行的检查项。'), ('@return the checks to apply', '@return 要应用的检查'), ('{@link BeanDefinitionRegistryPostProcessor} to report warnings.', '{@link BeanDefinitionRegistryPostProcessor} 用于报告警告。'), ('A single check that can be applied.', '可应用的单个检查项。'), ('Returns a warning if the check fails or {@code null} if there are no problems.', '检查失败时返回警告信息，无问题时返回 {@code null}。'), ('{@link Check} for {@code @ComponentScan} on problematic package.', '{@link Check} 针对有问题的包上 {@code @ComponentScan}。')], 'SpringApplicationBuilder.java': [('Builder for {@link SpringApplication} and {@link ApplicationContext} instances with\n * convenient fluent API and context hierarchy support.', '用于构建 {@link SpringApplication} 与 {@link ApplicationContext} 实例的构建器，提供流式 API 与上下文层次结构支持。'), ('If your needs are simpler, consider using the static convenience methods in\n * SpringApplication instead.', '若需求较简单，可考虑直接使用 SpringApplication 的静态便捷方法。')], 'CloudFoundryVcapEnvironmentPostProcessor.java': [('An {@link EnvironmentPostProcessor} that knows where to find VCAP (a.k.a. Cloud\n * Foundry) metadata in the existing environment.', '从现有环境中查找 VCAP（即 Cloud Foundry）元数据的 {@link EnvironmentPostProcessor}。'), ('N.B. this initializer is mainly intended for informational use', '注意：此初始化器主要用于信息用途'), ('Create a new {@link CloudFoundryVcapEnvironmentPostProcessor} instance.', '创建新的 {@link CloudFoundryVcapEnvironmentPostProcessor} 实例。'), ('@param logFactory the log factory to use', '@param logFactory 要使用的日志工厂')], 'BootstrapRegistry.java': [('A simple object registry that is available during startup and {@link Environment}\n * post-processing up to the point that the {@link ApplicationContext} is prepared.', '在启动及 {@link Environment} 后处理期间、直至 {@link ApplicationContext} 准备完成前可用的简单对象注册表。'), ('The registry uses {@link Class} as a key, meaning that only a single instance of a\n * given type can be stored.', '注册表以 {@link Class} 为键，即每种类型只能存储一个实例。'), ('Register a specific type with the registry.', '向注册表注册指定类型。'), ('Supplier used to provide the actual instance when needed.', '在需要时提供实际实例的供应者。'), ('The scope of an instance.', '实例的作用域。'), ('A singleton instance.', '单例实例。'), ('A prototype instance.', '原型实例。')]}


def apply_replacements(text: str, replacements: list[tuple[str, str]]) -> str:
    for old, new in replacements:
        if old not in text:
            raise ValueError(f"Pattern not found:\n{old[:160]}...")
        text = text.replace(old, new, 1)
    return text


def has_chinese(text: str) -> bool:
    return bool(re.search(r"[\u4e00-\u9fff]", text))


def mark_queue_done(files: list[str]) -> None:
    done_path = QUEUE / "done.txt"
    pending_path = QUEUE / "pending.txt"
    done = [ln.strip() for ln in done_path.read_text(encoding="utf-8").splitlines() if ln.strip()]
    pending = [ln.strip() for ln in pending_path.read_text(encoding="utf-8").splitlines() if ln.strip()]
    done_set = set(done)
    pending_set = set(pending)
    for rel in files:
        if rel not in done_set:
            done.append(rel)
            done_set.add(rel)
        pending_set.discard(rel)
    done_path.write_text(("\n".join(done) + ("\n" if done else "")), encoding="utf-8")
    pending = [ln for ln in pending if ln in pending_set]
    pending_path.write_text(("\n".join(pending) + ("\n" if pending else "")), encoding="utf-8")
    batch_path = QUEUE / "batch.json"
    batch = json.loads(batch_path.read_text(encoding="utf-8"))
    batch["done"] = len(done)
    batch["remaining_pending"] = len(pending)
    batch_path.write_text(json.dumps(batch, ensure_ascii=False, indent=2) + "\n", encoding="utf-8")


def main() -> int:
    failures: list[str] = []
    ok = 0
    for rel in BATCH_FILES:
        name = Path(rel).name
        src = ORIGINAL / rel
        dst = ANALYZED / rel
        if not src.exists():
            failures.append(f"MISSING original: {rel}")
            continue
        dst.parent.mkdir(parents=True, exist_ok=True)
        if not dst.exists() or not has_chinese(dst.read_text(encoding="utf-8")):
            shutil.copy2(src, dst)
        reps = FILE_REPLACEMENTS.get(name, [])
        if not reps:
            failures.append(f"NO_REPLACEMENTS: {rel}")
            continue
        try:
            text = dst.read_text(encoding="utf-8")
            if has_chinese(text):
                cn_lines = len(re.findall(r"[\u4e00-\u9fff]", text))
                if cn_lines > 20:
                    ok += 1
                    print(f"SKIP(already CN) {rel}")
                    continue
            text = apply_replacements(text, reps)
            if not has_chinese(text):
                failures.append(f"NO_CHINESE_AFTER: {rel}")
                continue
            dst.write_text(text, encoding="utf-8")
            ok += 1
            print(f"OK {rel}")
        except Exception as e:
            failures.append(f"{rel}: {e}")
            print(f"FAIL {rel}: {e}")
    if not failures:
        mark_queue_done(BATCH_FILES)
        print("Marked 20 files done in queue")
    print(json.dumps({"ok": ok, "failures": failures}, ensure_ascii=False, indent=2))
    return 1 if failures else 0


if __name__ == "__main__":
    raise SystemExit(main())
